mkuse!{use std :: fmt ;}
mkuse!{# [cfg (feature = "nightly")] use rustc_macros :: HashStable_Generic ;}
mkuse!{use crate :: ExternAbi ;}
mkitem!{mkenum!{# [doc = " Calling convention to determine codegen"] # [doc = ""] # [doc = " CanonAbi erases certain distinctions ExternAbi preserves, but remains target-dependent."] # [doc = " There are still both target-specific variants and aliasing variants, though much fewer."] # [doc = " The reason for this step is the frontend may wish to show an ExternAbi but implement that ABI"] # [doc = " using a different ABI than the string per se, or describe irrelevant differences, e.g."] # [doc = " - extern \"system\""] # [doc = " - extern \"cdecl\""] # [doc = " - extern \"C-unwind\""] # [doc = " In that sense, this erases mere syntactic distinctions to create a canonical *directive*,"] # [doc = " rather than picking the \"actual\" ABI."] # [derive (Copy , Clone , Debug)] # [derive (PartialOrd , Ord , PartialEq , Eq , Hash)] # [cfg_attr (feature = "nightly" , derive (HashStable_Generic))] pub enum CanonAbi { C , Rust , RustCold , # [doc = " An ABI that rustc does not know how to call or define."] Custom , # [doc = " ABIs relevant to 32-bit Arm targets"] Arm (ArmCall) , # [doc = " ABI relevant to GPUs: the entry point for a GPU kernel"] GpuKernel , # [doc = " ABIs relevant to bare-metal interrupt targets"] Interrupt (InterruptKind) , # [doc = " ABIs relevant to Windows or x86 targets"] X86 (X86Call) , }}}
mkitem!{mkimpl!{impl fmt :: Display for CanonAbi { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { let erased_abi = match self { CanonAbi :: C => ExternAbi :: C { unwind : false } , CanonAbi :: Rust => ExternAbi :: Rust , CanonAbi :: RustCold => ExternAbi :: RustCold , CanonAbi :: Custom => ExternAbi :: Custom , CanonAbi :: Arm (arm_call) => match arm_call { ArmCall :: Aapcs => ExternAbi :: Aapcs { unwind : false } , ArmCall :: CCmseNonSecureCall => ExternAbi :: CmseNonSecureCall , ArmCall :: CCmseNonSecureEntry => ExternAbi :: CmseNonSecureEntry , } , CanonAbi :: GpuKernel => ExternAbi :: GpuKernel , CanonAbi :: Interrupt (interrupt_kind) => match interrupt_kind { InterruptKind :: Avr => ExternAbi :: AvrInterrupt , InterruptKind :: AvrNonBlocking => ExternAbi :: AvrNonBlockingInterrupt , InterruptKind :: Msp430 => ExternAbi :: Msp430Interrupt , InterruptKind :: RiscvMachine => ExternAbi :: RiscvInterruptM , InterruptKind :: RiscvSupervisor => ExternAbi :: RiscvInterruptS , InterruptKind :: X86 => ExternAbi :: X86Interrupt , } , CanonAbi :: X86 (x86_call) => match x86_call { X86Call :: Fastcall => ExternAbi :: Fastcall { unwind : false } , X86Call :: Stdcall => ExternAbi :: Stdcall { unwind : false } , X86Call :: SysV64 => ExternAbi :: SysV64 { unwind : false } , X86Call :: Thiscall => ExternAbi :: Thiscall { unwind : false } , X86Call :: Vectorcall => ExternAbi :: Vectorcall { unwind : false } , X86Call :: Win64 => ExternAbi :: Win64 { unwind : false } , } , } ; erased_abi . as_str () . fmt (f) } }}}
mkitem!{mkenum!{# [doc = " Callee codegen for interrupts"] # [doc = ""] # [doc = " This is named differently from the \"Call\" enums because it is different:"] # [doc = " these \"ABI\" differences are not relevant to callers, since there is \"no caller\"."] # [doc = " These only affect callee codegen. making their categorization as distinct ABIs a bit peculiar."] # [derive (Copy , Clone , Debug)] # [derive (PartialOrd , Ord , PartialEq , Eq , Hash)] # [cfg_attr (feature = "nightly" , derive (HashStable_Generic))] pub enum InterruptKind { Avr , AvrNonBlocking , Msp430 , RiscvMachine , RiscvSupervisor , X86 , }}}
mkitem!{mkenum!{# [doc = " ABIs defined for x86-{32,64}"] # [doc = ""] # [doc = " One of SysV64 or Win64 may alias the C ABI, and arguably Win64 is cross-platform now?"] # [derive (Clone , Copy , Debug)] # [derive (PartialOrd , Ord , PartialEq , Eq , Hash)] # [cfg_attr (feature = "nightly" , derive (HashStable_Generic))] pub enum X86Call { # [doc = " \"fastcall\" has both GNU and Windows variants"] Fastcall , # [doc = " \"stdcall\" has both GNU and Windows variants"] Stdcall , SysV64 , Thiscall , Vectorcall , Win64 , }}}
mkitem!{mkenum!{# [doc = " ABIs defined for 32-bit Arm"] # [derive (Copy , Clone , Debug)] # [derive (PartialOrd , Ord , PartialEq , Eq , Hash)] # [cfg_attr (feature = "nightly" , derive (HashStable_Generic))] pub enum ArmCall { Aapcs , CCmseNonSecureCall , CCmseNonSecureEntry , }}}